//! Built-in click and typing sound effects (generated by `scripts/make-sounds.py`), embedded in
//! the binary and placed identically by the editor preview and the exporter.

use std::collections::HashMap;
use std::sync::{Arc, Mutex, OnceLock};

macro_rules! sounds {
    ($($name:literal),* $(,)?) => {
        const FILES: &[(&str, &[u8])] = &[$(($name, include_bytes!(concat!("../assets/sounds/", $name, ".wav")))),*];
    };
}

sounds!(
    "click-classic-0", "click-classic-1", "click-classic-2", "click-crisp-0", "click-crisp-1", "click-crisp-2", "click-soft-0", "click-soft-1", "click-soft-2",
    "key-mechanical-0", "key-mechanical-1", "key-mechanical-2", "key-mechanical-3", "key-mechanical-4", "key-mechanical-enter", "key-mechanical-space",
    "key-soft-0", "key-soft-1", "key-soft-2", "key-soft-3", "key-soft-4", "key-soft-enter", "key-soft-space",
    "key-thock-0", "key-thock-1", "key-thock-2", "key-thock-3", "key-thock-4", "key-thock-enter", "key-thock-space",
);

pub const CLICK_STYLES: [(&str, &str); 3] = [("soft", "Soft"), ("crisp", "Crisp"), ("classic", "Classic")];
pub const KEY_STYLES: [(&str, &str); 3] = [("mechanical", "Mechanical"), ("soft", "Soft"), ("thock", "Thock")];

/// One decoded sound: 48 kHz stereo, interleaved.
pub type Pcm = Arc<Vec<f32>>;

pub struct SoundSet {
    pub normal: Vec<Pcm>,
    pub space: Option<Pcm>,
    pub enter: Option<Pcm>,
}

/// Decode a 16-bit PCM WAV to 48 kHz stereo.
pub fn decode_wav(bytes: &[u8]) -> Option<Vec<f32>> {
    if bytes.len() < 44 || &bytes[0..4] != b"RIFF" {
        return None;
    }
    let (mut pos, mut rate, mut ch, mut bits) = (12usize, 44_100u32, 1u16, 16u16);
    let mut data: &[u8] = &[];
    while pos + 8 <= bytes.len() {
        let id = &bytes[pos..pos + 4];
        let size = u32::from_le_bytes(bytes[pos + 4..pos + 8].try_into().ok()?) as usize;
        let body = bytes.get(pos + 8..(pos + 8 + size).min(bytes.len()))?;
        match id {
            b"fmt " if body.len() >= 16 => {
                ch = u16::from_le_bytes(body[2..4].try_into().ok()?);
                rate = u32::from_le_bytes(body[4..8].try_into().ok()?);
                bits = u16::from_le_bytes(body[14..16].try_into().ok()?);
            }
            b"data" => data = body,
            _ => {}
        }
        pos += 8 + size + (size & 1);
    }
    if bits != 16 || ch == 0 {
        return None;
    }
    let frames = data.len() / (2 * ch as usize);
    let sample = |f: usize, c: usize| i16::from_le_bytes([data[(f * ch as usize + c) * 2], data[(f * ch as usize + c) * 2 + 1]]) as f32 / 32768.0;
    let mut stereo = Vec::with_capacity(frames * 2);
    for f in 0..frames {
        let l = sample(f, 0);
        let r = if ch > 1 { sample(f, 1) } else { l };
        stereo.push(l);
        stereo.push(r);
    }
    if rate == 48_000 {
        return Some(stereo);
    }
    let ratio = rate as f64 / 48_000.0;
    let out_frames = (frames as f64 / ratio) as usize;
    let mut out = Vec::with_capacity(out_frames * 2);
    for i in 0..out_frames {
        let pos = i as f64 * ratio;
        let a = pos as usize;
        let b = (a + 1).min(frames.saturating_sub(1));
        let f = (pos - a as f64) as f32;
        for c in 0..2 {
            out.push(stereo[a * 2 + c] * (1.0 - f) + stereo[b * 2 + c] * f);
        }
    }
    Some(out)
}

fn cache() -> &'static Mutex<HashMap<String, Option<Pcm>>> {
    static C: OnceLock<Mutex<HashMap<String, Option<Pcm>>>> = OnceLock::new();
    C.get_or_init(|| Mutex::new(HashMap::new()))
}

fn load(name: &str) -> Option<Pcm> {
    let mut c = cache().lock().unwrap();
    if let Some(v) = c.get(name) {
        return v.clone();
    }
    let v = FILES.iter().find(|(n, _)| *n == name).and_then(|(_, b)| decode_wav(b)).map(Arc::new);
    c.insert(name.to_string(), v.clone());
    v
}

/// The sound set for `kind` ("click" or "key") in `style`.
pub fn load_set(kind: &str, style: &str) -> SoundSet {
    if kind == "click" {
        let normal = (0..3).filter_map(|i| load(&format!("click-{style}-{i}"))).collect();
        return SoundSet { normal, space: None, enter: None };
    }
    let normal: Vec<Pcm> = (0..5).filter_map(|i| load(&format!("key-{style}-{i}"))).collect();
    let first = normal.first().cloned();
    SoundSet { space: load(&format!("key-{style}-space")).or_else(|| first.clone()), enter: load(&format!("key-{style}-enter")).or(first), normal }
}

/// Deterministic "randomness" from the event time, so preview and export agree.
pub fn hash(t_ms: f64) -> f64 {
    let v = (t_ms * 10.0).round() as i64 as i32;
    (v.wrapping_mul(-1_640_531_535i32 /* 2654435761 as i32 */) as u32) as f64 / 4_294_967_296.0
}

/// A placed hit: output start frame, its sound, resampling rate and gain.
pub struct Hit {
    pub start_frame: i64,
    pub pcm: Pcm,
    pub rate: f64,
    pub gain: f32,
}

/// Place one hit per mark. `kind` of a key mark: 1 space, 2 return.
pub fn place(set: &SoundSet, marks: &[(f64, u8)]) -> Vec<Hit> {
    if set.normal.is_empty() {
        return Vec::new();
    }
    marks
        .iter()
        .map(|(t, kind)| {
            let h = hash(*t);
            let mut pcm = set.normal[((h * set.normal.len() as f64).floor() as usize) % set.normal.len()].clone();
            if *kind == 1 {
                if let Some(s) = &set.space {
                    pcm = s.clone();
                }
            } else if *kind == 2 {
                if let Some(e) = &set.enter {
                    pcm = e.clone();
                }
            }
            Hit { start_frame: (t * 48.0).round() as i64, pcm, rate: 0.96 + h * 0.08, gain: (0.82 + hash(t + 17.0) * 0.18) as f32 }
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_embedded_sound_decodes() {
        for (n, b) in FILES {
            let pcm = decode_wav(b).unwrap_or_else(|| panic!("{n} did not decode"));
            assert!(pcm.len() > 100, "{n}");
        }
    }

    #[test]
    fn sets_are_complete() {
        for (s, _) in CLICK_STYLES {
            assert_eq!(load_set("click", s).normal.len(), 3);
        }
        for (s, _) in KEY_STYLES {
            let set = load_set("key", s);
            assert_eq!(set.normal.len(), 5);
            assert!(set.space.is_some() && set.enter.is_some());
        }
    }

    #[test]
    fn hash_is_stable() {
        assert_eq!(hash(1234.5), hash(1234.5));
        assert!((0.0..1.0).contains(&hash(98765.4)));
    }
}
